mapper.update:
UPDATE TB_BSSL001
   SET SLOT_ST_CD    = #{slot.slotState}
      ,OCPP_CONN_ST  = #{slot.ocppConnectorStatus}
      ,BAT_SN        = #{slot.batterySerialNo}
      ,CUR_SOC       = #{slot.currentSoC}
      ,CUR_SOH       = #{slot.currentSoH}
      ,PROD_DT       = #{slot.productionDate}
      ,VENDOR_INFO   = #{slot.vendorInfo}
      ,CH_ST_DT      = #{slot.chargingStartDate}
      ,EST_RDY_DT    = #{slot.estimatedReadyDate}
      ,RSV_REQ_ID    = #{slot.reservedRequestId}
      ,RSV_UNTIL_DT  = #{slot.reservedUntil}
      ,FLT_CD        = #{slot.faultCode}
      ,FLT_SINCE_DT  = #{slot.faultedSince}
      ,LAST_EVT_TP   = #{slot.lastEventType}
      ,LAST_EVT_DT   = #{slot.lastEventDate}
      ,UPD_DT        = #{slot.writer.updateDate}
      ,UPD_ID        = #{slot.writer.updUserId}
 WHERE CP_ID   = #{slot.cpId}
   AND CS_ID   = #{slot.csId}
   AND EVSE_ID = #{slot.evseId}

mapper.delete:
